import java.util.Scanner;

public class Main {
    static final long MOD_CONST = 1000000007;
    static long number_input;
    static int digit_count, base_number, total_result, position_index, digits_array[] = new int[110];

    static void add_mod(int[] x, int y, int m) {
        x[0] += y;
        if (x[0] >= m)
            x[0] -= m;
    }

    static class Matrix {
        int[][] mat;

        Matrix() {
            mat = new int[35][35];
        }

        static Matrix multiply(Matrix a, Matrix b) {
            Matrix res = new Matrix();
            for (int k = 0; k <= a.mat.length - 1; k++)
                for (int i = 0; i < a.mat.length; i++)
                    if (a.mat[i][k] != 0)
                        for (int j = 0; j < a.mat.length; j++)
                            if (b.mat[k][j] != 0) {
                                long val = (1L * a.mat[i][k] * b.mat[k][j] + res.mat[i][j]) % MOD_CONST;
                                res.mat[i][j] = (int) val;
                            }
            return res;
        }
    }

    static Matrix answerMatrix, sMatArr[][] = new Matrix[75][35], prefixMatArr[][] = new Matrix[75][35],
            suffixMatArr[][] = new Matrix[75][35];

    static void parseNumber(long number) {
        long temp = number;
        digit_count = 0;
        while (temp != 0) {
            digits_array[++digit_count] = (int) (temp % base_number);
            temp /= base_number;
        }
        // reverse the array from index 1 to digit_count
        for (int i = 1; i <= digit_count / 2; i++) {
            int tempVal = digits_array[i];
            digits_array[i] = digits_array[digit_count - i + 1];
            digits_array[digit_count - i + 1] = tempVal;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        number_input = sc.nextLong();
        base_number = sc.nextInt();
        parseNumber(number_input);

        int n = base_number + 1; // size for matrices

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sMatArr[0][i] = new Matrix();
                sMatArr[0][i].mat[j][j] = 1;
                sMatArr[0][i].mat[i][j] = 1;
            }
        }

        for (int i = 1; i <= digit_count; i++) {
            int idx = i - 1;
            prefixMatArr[idx][0] = sMatArr[idx][0];
            suffixMatArr[idx][base_number - 1] = sMatArr[idx][base_number - 1];

            for (int j = 1; j < base_number; j++)
                prefixMatArr[idx][j] = Matrix.multiply(prefixMatArr[idx][j - 1], sMatArr[idx][j]);

            for (int j = base_number - 2; j >= 0; j--)
                suffixMatArr[idx][j] = Matrix.multiply(sMatArr[idx][j], suffixMatArr[idx][j + 1]);

            for (int j = 0; j < base_number; j++) {
                if (j > 0)
                    sMatArr[idx + 1][j] = Matrix.multiply(suffixMatArr[idx][j], prefixMatArr[idx][j - 1]);
                else
                    sMatArr[idx + 1][j] = suffixMatArr[idx][j];
            }
        }

        int size = base_number + 1;
        answerMatrix = new Matrix();
        for (int i = 0; i < size; i++)
            for (int j = 0; j < size; j++)
                answerMatrix.mat[i][j] = (i == j) ? 1 : 0;

        position_index = 0;

        for (int i = 1; i <= digit_count; i++) {
            int idx = i - 1;
            int d = digits_array[i];
            if (d != 0) {
                if (position_index + d - 1 >= base_number) {
                    for (int j = position_index; j < base_number; j++) {
                        answerMatrix = Matrix.multiply(answerMatrix, sMatArr[idx][j]);
                    }
                    for (int j = 0; j <= (position_index + d - 1) - base_number; j++) {
                        answerMatrix = Matrix.multiply(answerMatrix, sMatArr[idx][j]);
                    }
                } else {
                    for (int j = position_index; j <= position_index + d - 1; j++) {
                        answerMatrix = Matrix.multiply(answerMatrix, sMatArr[idx][j]);
                    }
                }
                add_mod(new int[] { position_index }, d, base_number);
            } else {
                // if d == 0, do nothing
            }
        }

        total_result = 0;
        for (int i = 0; i <= base_number; i++) {
            total_result += answerMatrix.mat[i][base_number];
            if (total_result >= MOD_CONST)
                total_result -= MOD_CONST;
        }
        System.out.println(total_result);
        sc.close();
    }
}
